        private static void SpanishJournal(UnityEngine.Localization.Tables.StringTable t)
        {
            t.AddEntry("journal luminice 3", "El pueblo de <b><#805D46>Snowdwell</color></b> está construido alrededor del glaciar masivo de Luminice, proporcionando a sus habitantes una atmósfera cálida, luz suave y agua potable. Creando un refugio seguro del frío implacable.");
            t.AddEntry("journal shades title", "Sombras");
            t.AddEntry("journal luminice 2", "Estos fragmentos de Luminice poseen una habilidad única que amplifica los efectos de aquellos que los sostienen o de los objetos en los que están infusionados.");
            t.AddEntry("journal luminice 1", "El Luminice se forma durante un fenómeno raro donde el agua de las aguas termales que erupcionan se congelan instantáneamente, creando un tipo especial de hielo que se siente cálido al tacto.");
            t.AddEntry("journal gnomes title", "Gnomos");
            t.AddEntry("journal wildfrost title", "EL WILDFROST");
            t.AddEntry("journal wildfrost part 1", "Cuando comenzó a nevar y la temperatura bajó, supimos que era una tormenta como ninguna otra. A medida que pasaban los meses, la nieve persistía y el frío se volvía más duro. No había escapatoria del <b>WILDFROST</b>, ya que se extendía como un incendio de nieve y hielo.");
            t.AddEntry("journal wildfrost part 2", "Muchos creían que la tormenta tenía un origen antinatural. Valientes aventureros se adentraron en la naturaleza, decididos a poner fin a la tormenta...");
            t.AddEntry("journal wildfrost part 3", "Yo también decidí asumir el desafío. Pero, como aquellos que vinieron antes que yo, no pude penetrar el corazón de la tormenta...");
            t.AddEntry("journal wildfrost part 4", "Si alguien está leyendo esto, use el conocimiento dentro de estas páginas para avanzar y traer el sol de vuelta a nuestro mundo. Juntos, podemos recuperar la calidez y la luz de esta tierra congelada.");
            t.AddEntry("journal sun title", "EL SOL");
            t.AddEntry("journal sun part 1", "Hace muchos años, antes del invierno eterno, había un espíritu poderoso en el cielo conocido como el <b>SOL</b>.");
            t.AddEntry("journal sun part 2", "El Sol era la esencia de toda la vida, su luz radiante proporcionaba calidez y nutrición a todos los seres vivos.");
            t.AddEntry("journal sun part 3", "La luz dorada no duró para siempre...\nUna terrible tormenta descendió sobre la tierra, engullendo al Sol y dejando un cubo de hielo sin vida en el cielo. Ahora, todo lo que queda es una luz tenue y vacía que no ofrece calidez ni consuelo.");
            t.AddEntry("journal shades part 1", "<b><#825A43>Antes del Wildfrost</color></b><line-height=0.9>\n</line-height>Las sombras eran criaturas esquivas conocidas por su capacidad para poseer objetos. Estos seres raramente vistos podían encontrarse ocasionalmente en lugares oscuros y fríos como conchas y ollas.");
            t.AddEntry("journal shades part 2", "<b><#643D34>Después del Wildfrost</color></b><line-height=0.9>\n</line-height>A medida que el mundo se volvía más frío y oscuro, las sombras se volvieron más dominantes y poderosas. Comenzaron a poseer objetos peligrosos y animarlos en oponentes monstruosos.");
            t.AddEntry("journal shades part 3", "Una tribu conocida como los <b><#643D34>Sombramantes</color></b> encontraron una manera de aprovechar el poder de estas criaturas. Usando máscaras diseñadas de manera única, ¡pudieron convertirlas en aliados confiables!");
            t.AddEntry("journal gnomes part 1", "<b><#825A43>Antes del Wildfrost</color></b>\nLos gnomos eran una raza pacífica que pasaba sus días reparando Cachivaches y construyendo magníficas máquinas.");
            t.AddEntry("journal gnomes part 2", "<b><#643D34>Después del Wildfrost</color></b>\nLos gnomos restantes se unieron y desarrollaron nuevos Cachivaches para ayudarlos a navegar el frío y duro entorno.");
            t.AddEntry("journal gnomes part 3", "Su próspera ciudad de <b><#245356>Gnomolandia</color></b> se perdió durante la tormenta, pero los gnomos prosperarom. Eventualmente, encontraron su camino a Snowdwell y se unieron a las filas en la lucha contra el Wildfrost...");
            t.AddEntry("journal luminice title", "Luminice");
            t.AddEntry("journal luminice note 1", "presión humeante");
            t.AddEntry("journal luminice note 2", "viento frío");
            t.AddEntry("journal luminice note 3", "¡núcleo de Luminice!");
            t.AddEntry("journal luminice note 4", "Mochila de viaje infusionada con Luminice. ¡Puede contener más de lo que parece!");
            t.AddEntry("journal frost guardian title", "La Sombra del Emperador");
            t.AddEntry("journal frost guardian 1", "A medida que nos acercábamos al ojo de la tormenta, gruñidos y rugidos resonando a través de los vientos helados, encontramos esta sombra de otro mundo...");
            t.AddEntry("journal frost guardian 2", "Criaturas atormentadas se agolpaban a su alrededor como si estuvieran bajo su hechizo...");
            t.AddEntry("journal frost guardian 3", "Esta sombra... ¡puede poseer no solo objetos inanimados, sino también seres vivos! <#D87B66>Pelear contra ella es inútil...");
            t.AddEntry("journal frost guardian 4", "Debo regresar y advertir a los demás...");
            t.AddEntry("journal frost guardian 5", "¡NO TE ACERQUES A ELLA BAJO NINGÚN MOTIVO!");
        }

